7	/**
8	 * Assigns the owner's {@code customerCode} before it is saved. The code is formatted
9	 * {@code <LAST3>-<NNNN>}, where {@code LAST3} is the upper-cased first three letters of the
10	 * last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to one more than
11	 * the current number of owners (e.g. {@code SMI-0007}). Mutates the entity in place so
12	 * {@link SaveOwner} persists it.
13	 */
14	public class AssignCustomerCode {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String lastName = owner.getLastName();
18	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
19	        int sequence = ownerRepository.findAll().size() + 1;
20	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
21	    }
22	}
