6	/**
7	 * Assigns the owner's {@code membershipNumber} before it is saved. The number is formatted
8	 * {@code <customerCode>-M<YY>}, where {@code customerCode} is the owner's customer code and
9	 * {@code YY} is the last two digits of the {@code registrationDate} year, zero-padded
10	 * (e.g. {@code SMI-0007-M26}). Runs after {@link AssignCustomerCode} has set the customer code
11	 * and {@link BuildOwner} has set the registration date, so both inputs are present. Mutates the
12	 * entity in place so {@link SaveOwner} persists it.
13	 */
14	public class AssignMembershipNumber {
15	
16	    public void service(@Val Owner owner) {
17	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
18	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
19	    }
20	}
